insert into propiedades(codigo,direccion,localidad,etiquetas,de_amia,anio_venta,valor_venta,moneda_venta,obs,situacion_legal)
select 'INM-'||lpad((base.b+d.ord)::text,3,'0'),d.direccion,d.localidad,d.etiquetas,d.de_amia,d.anio_venta,d.valor_venta,
       case when d.valor_venta is not null then 'USD' end,d.obs,d.situacion_legal
from d cross join base
where not exists (select 1 from propiedades p where upper(p.direccion)=upper(d.direccion));

select count(*) as inmuebles_en_la_base from propiedades;   -- tiene que dar 130 (o más, si ya tenías propiedades de prueba)
